class Solution {
    string s;
    int pos = 0;
    using Words = set<string>;

    Words expression() {
        Words result;
        while (true) {
            Words term = product();
            result.insert(term.begin(), term.end());
            if (pos >= static_cast<int>(s.size()) || s[pos] != ',') break;
            ++pos;
        }
        return result;
    }

    Words product() {
        Words result = {""};
        while (pos < static_cast<int>(s.size()) && s[pos] != '}' && s[pos] != ',') {
            Words part;
            if (s[pos] == '{') {
                ++pos;
                part = expression();
                ++pos; // consume '}'
            } else {
                part.insert(string(1, s[pos++]));
            }
            Words next;
            for (const string& a : result)
                for (const string& b : part) next.insert(a + b);
            result.swap(next);
        }
        return result;
    }
public:
    vector<string> braceExpansionII(string expressionText) {
        s = expressionText;
        pos = 0;
        Words words = expression();
        return vector<string>(words.begin(), words.end());
    }
};
